package com.mo.economy_system.common.network;
import org.junit.jupiter.api.Test;import java.util.List;import static org.junit.jupiter.api.Assertions.*;
class MarketDataMessagesTest{
 @Test void validatesSummaryAndFixedPage(){assertNotNull(MarketDataRequestMessage.summary(0));assertThrows(IllegalArgumentException.class,()->new MarketDataRequestMessage(0,MarketDataRequestPurpose.SUMMARY,1,0,MarketOrderFilter.ALL,""));assertThrows(IllegalArgumentException.class,()->new MarketDataRequestMessage(1,MarketDataRequestPurpose.PAGE,0,8,MarketOrderFilter.ALL,""));assertNotNull(new MarketDataRequestMessage(1,MarketDataRequestPurpose.PAGE,0,9,MarketOrderFilter.ALL,""));}
 @Test void validatesResponseKindsAndRevision(){assertEquals(4,MarketDataResponseMessage.invalidated(4,1,2).marketRevision());assertThrows(IllegalArgumentException.class,()->new MarketDataResponseMessage(MarketDataResponseKind.INVALIDATED,0,0,0,0,0,0,0,List.of()));assertThrows(IllegalArgumentException.class,()->new MarketDataResponseMessage(MarketDataResponseKind.SUMMARY,0,-1,0,0,0,0,0,List.of()));assertThrows(IllegalArgumentException.class,()->new MarketDataResponseMessage(MarketDataResponseKind.PAGE,1,0,0,9,1,0,0,List.of()));}
}
